const results = $input.all();

let totalReviews = 0;
const sentimentCounts = { positive: 0, neutral: 0, negative: 0 };
const priorityCounts = { low: 0, medium: 0, high: 0, critical: 0 };
const modeCounts = { llm: 0, rules: 0 };
const allTopics = [];
const allComplaints = [];

for (const item of results) {
  const data = item.json;
  totalReviews += data.summary.total_reviews;

  // Aggregate sentiment
  for (const [sentiment, count] of Object.entries(data.summary.sentiment_distribution)) {
    sentimentCounts[sentiment] = (sentimentCounts[sentiment] || 0) + count;
  }

  // Aggregate priority
  for (const [priority, count] of Object.entries(data.summary.priority_distribution)) {
    priorityCounts[priority] = (priorityCounts[priority] || 0) + count;
  }

  // Aggregate mode
  for (const [mode, count] of Object.entries(data.summary.mode_distribution)) {
    modeCounts[mode] = (modeCounts[mode] || 0) + count;
  }

  // Collect topics and complaints
  allTopics.push(...data.summary.top_topics);
  allComplaints.push(...data.summary.top_complaints);
}

// Count topic frequencies
const topicFreq = {};
for (const topic of allTopics) {
  topicFreq[topic] = (topicFreq[topic] || 0) + 1;
}
const topTopics = Object.entries(topicFreq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([topic]) => topic);

// Count complaint frequencies
const complaintFreq = {};
for (const complaint of allComplaints) {
  complaintFreq[complaint] = (complaintFreq[complaint] || 0) + 1;
}
const topComplaints = Object.entries(complaintFreq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([complaint]) => complaint);

const negativePct = ((sentimentCounts.negative / totalReviews) * 100).toFixed(1);
const criticalCount = priorityCounts.critical || 0;

return [
  {
    json: {
      totalReviews,
      sentimentCounts,
      priorityCounts,
      modeCounts,
      topTopics,
      topComplaints,
      negativePct,
      criticalCount
    }
  }
];

